Add these functions to `techpath_chatbot.py` below the database dictionaries:

```python
# --- Tool Functions ---

def get_student_info(student_name: str) -> dict:
    """Look up a student by name (case-insensitive partial match)"""
    for name, info in STUDENTS.items():
        if student_name.lower() in name.lower():
            return {"found": True, "name": name, **info}
    return {"found": False, "error": f"Student '{student_name}' not found"}


def get_course_info(course_name: str) -> dict:
    """Get course details (fee, duration, trainer)"""
    for name, info in COURSES.items():
        if course_name.lower() in name.lower():
            return {"found": True, "name": name, **info, "fee_display": f"Rs.{info['fee']:,}"}
    return {"found": False, "error": f"Course '{course_name}' not found"}


def list_students(course: str = None, city: str = None) -> dict:
    """List all students, optionally filtered"""
    results = []
    for name, info in STUDENTS.items():
        if course and course.lower() not in info["course"].lower():
            continue
        if city and city.lower() not in info["city"].lower():
            continue
        results.append({"name": name, **info})
    return {"total": len(results), "students": results}


def calculate_grade(marks: int) -> dict:
    """Calculate grade from marks"""
    if marks >= 80: grade, label = "A", "Distinction"
    elif marks >= 60: grade, label = "B", "First Class"
    elif marks >= 40: grade, label = "C", "Pass"
    else: grade, label = "F", "Fail"
    return {"marks": marks, "grade": grade, "label": label, "passed": marks >= 40}
```

Test the functions directly:
```python
if __name__ == "__main__":
    print(get_student_info("Rahul"))
    print(get_course_info("Python"))
    print(list_students(city="Bhopal"))
    print(calculate_grade(85))
```

Run and verify each function returns the expected output.

The LLM needs to know what functions are available and what arguments they accept. Add the tool definitions:

```python
# --- Tool Schemas (tell the LLM about your functions) ---

tools = [
    {
        "type": "function",
        "function": {
            "name": "get_student_info",
            "description": "Look up a student's marks, course, city, and email from the TechPath database",
            "parameters": {
                "type": "object",
                "properties": {
                    "student_name": {
                        "type": "string",
                        "description": "Full or partial name of the student"
                    }
                },
                "required": ["student_name"]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "get_course_info",
            "description": "Get fee, duration, and trainer for a course at TechPath Institute",
            "parameters": {
                "type": "object",
                "properties": {
                    "course_name": {
                        "type": "string",
                        "description": "Name of the course"
                    }
                },
                "required": ["course_name"]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "list_students",
            "description": "List students at TechPath, optionally filtered by course or city",
            "parameters": {
                "type": "object",
                "properties": {
                    "course": {"type": "string", "description": "Filter by course name (optional)"},
                    "city": {"type": "string", "description": "Filter by city (optional)"}
                },
                "required": []
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "calculate_grade",
            "description": "Calculate grade (A/B/C/F) and pass/fail from marks",
            "parameters": {
                "type": "object",
                "properties": {
                    "marks": {"type": "integer", "description": "Marks (0-100)"}
                },
                "required": ["marks"]
            }
        }
    }
]

# Map function names to actual functions
FUNCTION_MAP = {
    "get_student_info": get_student_info,
    "get_course_info": get_course_info,
    "list_students": list_students,
    "calculate_grade": calculate_grade,
}
```

Note how each tool schema has:
- `name` — matches the Python function name exactly
- `description` — tells the LLM when to use this tool
- `parameters` — defines arguments with types and descriptions
- `required` — which arguments are mandatory
